class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(n):
            if n <= 0:
                return 0
            count = 0
            for length in range(1, 10):  # max 9 digits for n < 10^9
                if 10**(length-1) > n:
                    break
                # Count numbers with exactly 'length' digits up to n
                if length == 1:
                    # Single digit numbers: 1-9
                    upper = min(n, 9)
                    if upper >= 1:
                        count += upper
                else:
                    # Numbers with 'length' digits
                    lower = 10**(length-1)
                    upper = min(n, 10**length - 1)
                    if upper < lower:
                        continue
                    # For each such number, check if beautiful
                    # But we need to count efficiently
                    # Let's iterate through all numbers with this length up to n
                    # This could be too slow for large ranges
                    # We need a smarter approach
                    pass
            return count

        # Brute force approach for now
        def is_beautiful(num):
            digits = [int(d) for d in str(num)]
            digit_sum = sum(digits)
            digit_product = 1
            for d in digits:
                digit_product *= d
            if digit_sum == 0:
                return False
            return digit_product % digit_sum == 0

        count = 0
        for num in range(l, r+1):
            if is_beautiful(num):
                count += 1
        return count

