sys.setrecursionlimit(1 << 25)
def solve():
    data = sys.stdin.read().split()
    K = int(data[0])
    S = data[1]
    T = data[2]
    n = len(S)
    m = len(T)
    if abs(n - m) > K:
        print("No")
        return
    @functools.lru_cache(maxsize=None)
    def dp(i, j, k):
        if k > K:
            return False
        if i == n and j == m:
            return True
        if i == n:
            # need to insert (m-j) characters
            return (m - j) <= k
        if j == m:
            return (n - i) <= k
        # Option 1: replace
        if S[i] != T[j]:
            if dp(i+1, j+1, k+1):
                return True
        else:
            if dp(i+1, j+1, k):
                return True
        # Option 2: delete S[i]
        if dp(i+1, j, k+1):
            return True
        # Option 3: insert T[j]
        if dp(i, j+1, k+1):
            return True
        return False
    import functools
    if dp(0, 0, 0):
        print("Yes")
    else:
        print("No")
