class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def canAchieve(target_len):
            # We want to check if we can make the longest run of identical chars <= target_len
            # with at most numOps flips.
            # DP: dp[i][ops] = (last_char, length_modulo_target_len_plus_1)
            # Actually we can think greedily: we need to ensure that no segment of same char exceeds target_len.
            # This is like we process the string and at each position we decide the character (0 or 1)
            # such that the current run of same char doesn't exceed target_len, using at most numOps flips.
            # The number of states is small: current run length and current char.

            # dp[run_len][char] = min flips used to reach a state where the current run has length run_len and char
            # run_len ranges from 1 to target_len (we cap at target_len)
            # Initialize with first character
            INF = float('inf')
            # State: (run_len_mod, char) -> min flips
            # run_len_mod from 1 to target_len
            dp = [[INF, INF] for _ in range(target_len + 1)]

            first = int(s[0])
            # If we keep it as is: 0 flips, run_len=1, char=first
            dp[1][first] = 0
            # If we flip it: 1 flip, run_len=1, char=1-first
            dp[1][1 - first] = 1

            for i in range(1, n):
                new_dp = [[INF, INF] for _ in range(target_len + 1)]
                cur = int(s[i])
                for run_len in range(1, target_len + 1):
                    for c in [0, 1]:
                        if dp[run_len][c] == INF:
                            continue
                        # Option 1: keep s[i] as c, extend the run
                        if cur == c:
                            flips = dp[run_len][c]
                            new_run_len = min(run_len + 1, target_len)
                            if new_dp[new_run_len][c] > flips:
                                new_dp[new_run_len][c] = flips
                        else:
                            # Option 2: keep s[i] as c, but flip s[i], start new run
                            flips = dp[run_len][c] + 1
                            if flips <= numOps:
                                new_dp[1][c] = min(new_dp[1][c], flips)

                        # Option 3: place char != c, start new run of length 1 with opposite char
                        new_c = 1 - c
                        if cur == new_c:
                            flips = dp[run_len][c]
                            if new_dp[1][new_c] > flips:
                                new_dp[1][new_c] = flips
                        else:
                            flips = dp[run_len][c] + 1
                            if flips <= numOps:
                                new_dp[1][new_c] = min(new_dp[1][new_c], flips)

                dp = new_dp

            # Check if any state has flips <= numOps
            for run_len in range(1, target_len + 1):
                for c in [0, 1]:
                    if dp[run_len][c] <= numOps:
                        return True
            return False

        # Binary search on the answer
        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if canAchieve(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo
